25 | func NewIssue(ctx context.Context, repo *repo_model.Repository, issue *issues_model.Issue, labelIDs []int64, uuids []string, assigneeIDs, projectIDs []int64) error {
26 | 	if err := issue.LoadPoster(ctx); err != nil {
27 | 		return err
28 | 	}
