86 | // ChangeTitle changes the title of this issue, as the given user.
87 | func ChangeTitle(ctx context.Context, issue *issues_model.Issue, doer *user_model.User, title string) error {
88 | 	oldTitle := issue.Title
89 | 	issue.Title = title
90 | 
91 | 	if oldTitle == title {
92 | 		return nil
93 | 	}
94 | 
95 | 	if err := issue.LoadRepo(ctx); err != nil {
96 | 		return err
97 | 	}
98 | 
99 | 	if user_model.IsUserBlockedBy(ctx, doer, issue.PosterID, issue.Repo.OwnerID) {
100 | 		if !access_model.IsUserRepoAdmin(ctx, issue.Repo, doer) {
101 | 			return user_model.ErrBlockedUser
102 | 		}
103 | 	}
104 | 
105 | 	if err := issues_model.ChangeIssueTitle(ctx, issue, doer, oldTitle); err != nil {
106 | 		return err
107 | 	}
108 | 
109 | 	var reviewNotifiers []*ReviewRequestNotifier
110 | 	if issue.IsPull && issues_model.HasWorkInProgressPrefix(oldTitle) && !issues_model.HasWorkInProgressPrefix(title) {
111 | 		if err := issue.LoadPullRequest(ctx); err != nil {
112 | 			return err
113 | 		}
114 | 
115 | 		var err error
116 | 		reviewNotifiers, err = PullRequestCodeOwnersReview(ctx, issue.PullRequest)
117 | 		if err != nil {
118 | 			log.Error("PullRequestCodeOwnersReview: %v", err)
119 | 		}
120 | 	}
121 | 
122 | 	notify_service.IssueChangeTitle(ctx, doer, issue, oldTitle)
123 | 	ReviewRequestNotify(ctx, issue, issue.Poster, reviewNotifiers)
124 | 
125 | 	return nil
126 | }
