149 | // DeleteIssue deletes an issue
150 | func DeleteIssue(ctx context.Context, doer *user_model.User, issue *issues_model.Issue) error {
151 | 	// load issue before deleting it
152 | 	if err := issue.LoadAttributes(ctx); err != nil {
153 | 		return err
154 | 	}
155 | 	if err := issue.LoadPullRequest(ctx); err != nil {
156 | 		return err
157 | 	}
158 | 
159 | 	// delete entries in database
160 | 	attachmentPaths, err := deleteIssue(ctx, issue)
161 | 	if err != nil {
162 | 		return err
163 | 	}
164 | 	for _, attachmentPath := range attachmentPaths {
165 | 		system_model.RemoveStorageWithNotice(ctx, storage.Attachments, "Delete issue attachment", attachmentPath)
166 | 	}
167 | 
168 | 	// delete pull request related git data
169 | 	if issue.IsPull {
170 | 		if err := issue.PullRequest.LoadBaseRepo(ctx); err != nil {
171 | 			return err
172 | 		}
173 | 		if err := git.RemoveRef(ctx, issue.PullRequest.BaseRepo, issue.PullRequest.GetGitHeadRefName()); err != nil {
174 | 			return err
175 | 		}
176 | 	}
177 | 
178 | 	notify_service.DeleteIssue(ctx, doer, issue)
179 | 
180 | 	return nil

146 | func repoAssignment() func(ctx *context.APIContext) {
147 | 	return func(ctx *context.APIContext) {
148 | 		userName := ctx.PathParam("username")
149 | 		repoName := ctx.PathParam("reponame")
150 | 
151 | 		var (
152 | 			owner *user_model.User
153 | 			err   error
154 | 		)
155 | 
156 | 		// Check if the user is the same as the repository owner.
157 | 		if ctx.IsSigned && strings.EqualFold(ctx.Doer.LowerName, userName) {
158 | 			owner = ctx.Doer
159 | 		} else {
160 | 			owner, err = user_model.GetUserByName(ctx, userName)
161 | 			if err != nil {
162 | 				if user_model.IsErrUserNotExist(err) {
163 | 					if redirectUserID, err := user_model.LookupUserRedirect(ctx, userName); err == nil {
164 | 						context.RedirectToUser(ctx.Base, ctx.Doer, userName, redirectUserID)
165 | 					} else if user_model.IsErrUserRedirectNotExist(err) {
166 | 						ctx.APIErrorNotFound()
167 | 					} else {
168 | 						ctx.APIErrorInternal(err)
169 | 					}
170 | 				} else {
171 | 					ctx.APIErrorInternal(err)
172 | 				}
173 | 				return
174 | 			}
175 | 		}
176 | 		ctx.Repo.Owner = owner
177 | 		ctx.ContextUser = owner
178 | 
179 | 		// Get repository.
180 | 		repo, err := repo_model.GetRepositoryByName(ctx, owner.ID, repoName)
181 | 		if err != nil {
182 | 			if repo_model.IsErrRepoNotExist(err) {
183 | 				redirectRepoID, err := repo_model.LookupRedirect(ctx, owner.ID, repoName)
184 | 				if err == nil {
185 | 					context.RedirectToRepo(ctx.Base, redirectRepoID)
186 | 				} else if repo_model.IsErrRedirectNotExist(err) {
187 | 					ctx.APIErrorNotFound()
188 | 				} else {
189 | 					ctx.APIErrorInternal(err)
190 | 				}
191 | 			} else {
192 | 				ctx.APIErrorInternal(err)
193 | 			}
194 | 			return
195 | 		}
196 | 
197 | 		repo.Owner = owner
198 | 		ctx.Repo.Repository = repo
199 | 
200 | 		{
201 | 			needTwoFactor, err := doerNeedTwoFactorAuth(ctx, ctx.Doer)
202 | 			if err != nil {
203 | 				ctx.APIErrorInternal(err)
204 | 				return
205 | 			}
206 | 			if needTwoFactor {
207 | 				ctx.Repo.Permission = access_model.PermissionNoAccess()
208 | 			} else {
209 | 				ctx.Repo.Permission, err = access_model.GetDoerRepoPermission(ctx, repo, ctx.Doer)
210 | 				if err != nil {
211 | 					ctx.APIErrorInternal(err)
212 | 					return
213 | 				}
214 | 			}
215 | 		}
216 | 
217 | 		if !ctx.Repo.Permission.HasAnyUnitAccessOrPublicAccess() {
218 | 			ctx.APIErrorNotFound()
219 | 			return
220 | 		}
221 | 
222 | 		if !ctx.TokenCanAccessRepo(repo) {
223 | 			ctx.APIErrorNotFound()
224 | 			return
225 | 		}
226 | 	}
227 | }

